<?php
declare(strict_types=1);final class TranscriptService{
static function link(int $uid,string $url,string $lang):int{if(!validate_media_url($url))throw new InvalidArgumentException('Unsupported media URL.');$p=platform_from_url($url);$d=db();$d->beginTransaction();try{$d->prepare("INSERT INTO transcripts(user_id,source_type,platform,source_url,language,status,created_at,updated_at) VALUES(?,'url',?,?,?,'queued',NOW(),NOW())")->execute([$uid,$p,$url,$lang]);$id=(int)$d->lastInsertId();$d->prepare("INSERT INTO jobs(user_id,transcript_id,job_type,payload,status,available_at,created_at,updated_at) VALUES(?,?,'url',?,'queued',NOW(),NOW(),NOW())")->execute([$uid,$id,json_encode(['url'=>$url,'platform'=>$p,'language'=>$lang])]);$d->prepare("INSERT INTO usage_ledger(user_id,transcript_id,units,reason,created_at) VALUES(?,?,1,'transcript request',NOW())")->execute([$uid,$id]);$d->commit();return $id;}catch(Throwable $e){$d->rollBack();throw $e;}}
static function upload(int $uid,array $f,string $lang):int{if(($f['error']??4)!==0)throw new RuntimeException('Upload failed.');if($f['size']>(int)config('UPLOAD_MAX_MB',500)*1048576)throw new RuntimeException('File too large.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if(!str_starts_with((string)$mime,'audio/')&&!str_starts_with((string)$mime,'video/'))throw new RuntimeException('Invalid audio/video file.');$dir=BASE_PATH.'/'.trim((string)config('UPLOAD_DIR','storage/uploads'),'/');if(!is_dir($dir))mkdir($dir,0750,true);$ext=preg_replace('/[^a-z0-9]/i','',pathinfo($f['name'],PATHINFO_EXTENSION));$name=bin2hex(random_bytes(20)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$name))throw new RuntimeException('Could not store upload.');$rel=trim((string)config('UPLOAD_DIR','storage/uploads'),'/').'/'.$name;$d=db();$d->beginTransaction();try{$d->prepare("INSERT INTO transcripts(user_id,source_type,platform,source_file,original_filename,language,status,created_at,updated_at) VALUES(?,'upload','file',?,?,?,'queued',NOW(),NOW())")->execute([$uid,$rel,substr($f['name'],0,255),$lang]);$id=(int)$d->lastInsertId();$d->prepare("INSERT INTO jobs(user_id,transcript_id,job_type,payload,status,available_at,created_at,updated_at) VALUES(?,?,'upload',?,'queued',NOW(),NOW(),NOW())")->execute([$uid,$id,json_encode(['file'=>$rel,'language'=>$lang])]);$d->prepare("INSERT INTO usage_ledger(user_id,transcript_id,units,reason,created_at) VALUES(?,?,1,'upload request',NOW())")->execute([$uid,$id]);$d->commit();return $id;}catch(Throwable $e){$d->rollBack();@unlink(BASE_PATH.'/'.$rel);throw $e;}}
static function process(array $j):void{$d=db();$p=json_decode($j['payload'],true)?:[];$d->prepare("UPDATE transcripts SET status='processing',updated_at=NOW() WHERE id=?")->execute([$j['transcript_id']]);try{if($j['job_type']==='url'){$base=rtrim((string)config('TRANSCRIPT_API_URL',''),'/');if(!$base)throw new RuntimeException('Set TRANSCRIPT_API_URL in .env.');$ch=curl_init($base.'/api/'.$p['platform'].'/transcript');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode(['url'=>$p['url'],'language'=>$p['language']]),CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>180,CURLOPT_HTTPHEADER=>array_filter(['Content-Type: application/json',config('TRANSCRIPT_API_TOKEN')?'Authorization: Bearer '.config('TRANSCRIPT_API_TOKEN'):null])]);$raw=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if(!$raw||$code<200||$code>=300)throw new RuntimeException('URL provider HTTP '.$code);$r=json_decode($raw,true)?:[];$seg=$r['segments']??(is_array($r['transcript']??null)?$r['transcript']:[]);$text=$r['text']??(is_string($r['transcript']??null)?$r['transcript']:'');if(!$text&&is_array($seg)){$parts=[];foreach($seg as $x){if(is_array($x))$parts[]=$x['text']??$x['content']??'';}$text=implode(' ',$parts);}}else{$api=(string)config('ASR_API_URL','');$key=(string)config('ASR_API_KEY','');if(!$api||!$key)throw new RuntimeException('Set ASR_API_URL and ASR_API_KEY in .env.');$ch=curl_init($api);$post=['model'=>config('ASR_MODEL','whisper-1'),'file'=>new CURLFile(BASE_PATH.'/'.$p['file'])];if($p['language']!=='auto')$post['language']=$p['language'];curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$post,CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>600,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$key]]);$raw=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if(!$raw||$code<200||$code>=300)throw new RuntimeException('ASR provider HTTP '.$code);$r=json_decode($raw,true)?:[];$text=$r['text']??'';$seg=$r['segments']??[];}if(!is_string($text)||trim($text)==='')throw new RuntimeException('Provider returned empty transcript.');$d->beginTransaction();$d->prepare("UPDATE transcripts SET transcript_text=?,provider_payload=?,status='completed',completed_at=NOW(),updated_at=NOW() WHERE id=?")->execute([$text,json_encode($r),$j['transcript_id']]);$d->prepare('DELETE FROM transcript_segments WHERE transcript_id=?')->execute([$j['transcript_id']]);$s=$d->prepare('INSERT INTO transcript_segments(transcript_id,sequence_no,start_seconds,end_seconds,content) VALUES(?,?,?,?,?)');foreach($seg as $i=>$v){if(!is_array($v))continue;$c=$v['text']??$v['content']??'';if(trim((string)$c)!=='')$s->execute([$j['transcript_id'],$i+1,$v['start']??$v['start_time']??0,$v['end']??$v['end_time']??0,$c]);}$d->prepare("UPDATE jobs SET status='completed',finished_at=NOW(),updated_at=NOW() WHERE id=?")->execute([$j['id']]);$d->commit();}catch(Throwable $e){if($d->inTransaction())$d->rollBack();app_log($e->getMessage());$d->prepare("UPDATE jobs SET status='failed',error_message=?,finished_at=NOW(),updated_at=NOW() WHERE id=?")->execute([substr($e->getMessage(),0,1500),$j['id']]);$d->prepare("UPDATE transcripts SET status='failed',error_message=?,updated_at=NOW() WHERE id=?")->execute([substr($e->getMessage(),0,1500),$j['transcript_id']]);}}
}
